package com.example

import com.example.ExamQuestionHelper.QSpec

object MusicLiveExamInstrumentsBank1 {
    private const val T = "පෙරදිග, දේශීය හා ලෝක වාද්‍ය භාණ්ඩ වර්ගීකරණය"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("භාරතීය හා දේශීය පංචතූර්ය නාද වර්ගීකරණයට අනුව සියලු වාද්‍ය භාණ්ඩ බෙදා දක්වන ප්‍රධාන කොටස් ගණන කීයද?", "5 කි", "4 කි", "3 කි", "6 කි", "ආතත, විතත, විතතාතත, ඝන සහ සුසිර යනු පංචතූර්ය වර්ගීකරණයේ කොටස් පහයි."),
        q("භාරතීය ශාස්ත්‍රීය වාද්‍ය භාණ්ඩ වර්ගීකරණයේදී 'තත වාද්‍ය' ලෙස හඳුන්වනු ලබන්නේ කුමන භාණ්ඩද?", "තන්තු කම්පනයෙන් නාද උපදවන භාණ්ඩ", "සම් තට්ටු කිරීමෙන් නාද උපදවන භාණ්ඩ", "සුළඟ පිඹීමෙන් නාද උපදවන භාණ්ඩ", "ලෝහ එකිනෙක ගැටීමෙන් නාද උපදවන භාණ්ඩ", "තන්තු හෙවත් කම්බි භාවිතයෙන් නාද නිපදවන සිතාරය, වයලීනය වැනි භාණ්ඩ තත වාද්‍ය වේ."),
        q("සම් පටලයක් මත අතින් හෝ කෝටුවකින් ගසා නාද උපදවන භාණ්ඩ අයත් කාණ්ඩය කුමක්ද?", "ආවනද්ධ (අවනද්ධ) වාද්‍ය", "සුසිර වාද්‍ය", "තත වාද්‍ය", "ඝන වාද්‍ය", "තබ්ලාව, ගැටබෙරය, දවුල ආදී සම් භාවිත කළ බෙර වර්ග අවනද්ධ ගණයට වැටේ."),
        q("බන්සූරිය, හොරණෑව, ෂැහනායි සහ හක්ගෙඩිය අයත් වන්නේ කුමන වාද්‍ය භාණ්ඩ කාණ්ඩයටද?", "සුසිර වාද්‍ය", "ඝන වාද්‍ය", "තත වාද්‍ය", "ආවනද්ධ වාද්‍ය", "වාතය පිඹීමෙන් නාදය උපදවන සියලු භාණ්ඩ සුසිර ගණයට අයත් වේ."),
        q("තාලම්පට, ඝණ්ඨාරය, ජල්තරංග සහ කයිතාලම අයත් වන්නේ කුමන වාද්‍ය භාණ්ඩ වර්ගයටද?", "ඝන වාද්‍ය", "සුසිර වාද්‍ය", "තත වාද්‍ය", "විතත වාද්‍ය", "ඝන ලෝහ, දැව හෝ පිඟන් මැටි වස්තු ගැටීමෙන් නාද උපදවන භාණ්ඩ ඝන වාද්‍ය වේ."),
        q("සම්පූර්ණයෙන්ම අතින් පමණක් වාදනය කරනු ලබන සම් බෙර පංචතූර්ය නාදයේ කුමන කොටසට අයත් වේද?", "ආතත", "විතත", "විතතාතත", "සුසිර", "අතින් පමණක් වයන ගැටබෙරය, යක්බෙරය, මද්දලය ආදිය ආතත ගණයට වැටේ."),
        q("පංචතූර්ය වර්ගීකරණයේදී 'විතත' නාමයෙන් හඳුන්වනු ලබන්නේ කුමන ආකාරයේ බෙරද?", "කඩිප්පු හෝ කෝටුවලින් පමණක් වයන බෙර", "අතින් පමණක් වයන බෙර", "තන්තු ඇති වීණා වර්ග", "පිඹින නළා වර්ග", "තම්මැට්ටම වැනි කඩිප්පු දෙකකින් වාදනය කරන බෙර විතත ගණයට අයත් වේ."),
        q("දවුල වැනි එක් පැත්තක් අතින්ද අනෙක් පැත්ත කඩිප්පුවෙන්ද වයන බෙර අයත් වන්නේ කුමන කොටසටද?", "විතතාතත", "ආතත", "ඝන", "සුසිර", "අත සහ කෝටුව යන දෙකම යොදා වයන දවුල විතතාතත වර්ගයට අයත් වේ."),
        q("උත්තර භාරතීය ශාස්ත්‍රීය ගායනයේදී ප්‍රධාන වශයෙන් 'ශ්‍රැති හෙවත් මූලික ස්වරය' ලබාදීමට භාවිත කරන තත වාද්‍යය කුමක්ද?", "තම්බුරාව", "සිතාරය", "සන්තූරය", "සාරංගිය", "ගායකයාට ස්ථිර ආධාර ස්වර පදනම (Drone) සපයන්නේ තම්බුරාවයි."),
        q("සාමාන්‍යයෙන් ශාස්ත්‍රීය ගායනය සඳහා භාවිත කරන ප්‍රධාන තම්බුරාවක ඇති මුළු තන්තු ගණන කීයද?", "4 කි", "7 කි", "2 කි", "12 කි", "තම්බුරාවේ ප්‍රධාන වශයෙන් තන්තු හතරක් (ප/ම, ජෝඩි ස, ස, මන්ද්‍ර ස) පවතී."),
        q("තම්බුරාවේ පළමු තන්තුව සාමාන්‍යයෙන් සුසර කරනු ලබන්නේ කුමන ස්වරයටද?", "මන්ද්‍ර පංචමයට (හෝ මධ්‍යමයට)", "තාර ගාන්ධාරයට", "කෝමල රිෂභයට", "තීව්‍ර මධ්‍යමයට", "පළමු තන්තුව රාගයේ ස්වභාවය අනුව පංචමයට, මධ්‍යමයට හෝ නිෂාදයට සුසර කෙරේ."),
        q("තම්බුරාවේ දෙවන සහ තුන්වන 'ජෝඩි තන්තු' දෙක සුසර කරන්නේ කුමන ස්වරයටද?", "මධ්‍ය සප්තකයේ ෂඩ්ජයට (ස)", "මන්ද්‍ර සප්තකයේ පංචමයට (ප)", "තාර සප්තකයේ ෂඩ්ජයට", "මධ්‍ය සප්තකයේ ධෛවතයට (ධ)", "මැද පිහිටි ජෝඩි තන්තු දෙකම මධ්‍ය ෂඩ්ජයට සමානව සුසර කරනු ලැබේ."),
        q("තම්බුරාවේ සිව්වන හෙවත් ඝනකමින් වැඩි පිත්තල තන්තුව සුසර කරන්නේ කුමන ස්වරයටද?", "මන්ද්‍ර ෂඩ්ජයට", "මධ්‍ය ගාන්ධාරයට", "තාර රිෂභයට", "මධ්‍ය පංචමයට", "සිව්වන තන්තුව 'ඛරජ්' ලෙස හඳුන්වන අතර එය මන්ද්‍ර සප්තකයේ ෂඩ්ජයට සුසර කෙරේ."),
        q("තම්බුරාවේ මිහිරි ජවාරි නාදය ඇති කිරීම සඳහා ඝෝරචය මත තන්තු යටින් තබන කුඩා නූල් කැබැල්ල කුමක්ද?", "ජීවා (Jeeva)", "මිස්රාබ්", "සියාහි", "පර්දා", "තන්තුව හා ඝෝරචය අතර තබන කුඩා කපු නූල නිසා තම්බුරාවේ මිහිරි නාදය උපදී."),
        q("තම්බුරාවේ තන්තු සියුම් ලෙස ස්වර ගැළපීම සඳහා පහළින් සවි කර ඇති පබළු හෝ අස්ථි කොටස් මොනවාද?", "මණ්කා", "ඛූන්ටි", "තුම්බා", "තාරගහන්", "තන්තුවල සියුම් ස්වර සුසර කිරීම සඳහා පහළ ලංගෝට් කොටස ආසන්නයේ මණ්කා තබා ඇත."),
        q("තම්බුරාවේ බඳ (අනුනාද පෙට්ටිය) නිර්මාණය කිරීම සඳහා බහුලව යොදාගන්නා ස්වාභාවික ඵලය කුමක්ද?", "වියළි ලබු කබල (තුම්බා)", "කොස් ලීය පමණක්", "පොල් කටුව", "උණ බම්බුව", "වියළා සකසාගත් විශාල ලබු ගෙඩියකින් තම්බුරාවේ හා සිතාරයේ තුම්බා නොහොත් බඳ සාදයි."),
        q("තම්බුරාවේ තන්තු සුසර කිරීම සඳහා ඉහළ කෙළවරේ සවි කර ඇති ලී ඇණ හඳුන්වන්නේ කෙසේද?", "ඛූන්ටි (සුසර ඇණ)", "පර්දා (ස්වර පටි)", "ගට්ටා", "චාන්ටි", "තන්තුවල ආතතිය වැඩි හෝ අඩු කර සුසර කිරීම සඳහා ඛූන්ටි කරකවනු ලැබේ."),
        q("සිතාරය හඳුන්වා දීමේ ගෞරවය හිමිවන 13 වන සියවසේ සිටි ප්‍රකට සංගීතවේදියා කවුද?", "අමීර් ඛුස්රෝ", "මියාන් තාන්සේන්", "භරතමුනි", "ශාර්ංගදේව", "පුරාණ ත්‍රිතන්ත්‍රී වීණාව වැඩිදියුණු කර අමීර් ඛුස්රෝ සිතාරය බිහි කළ බව සැලකේ."),
        q("සිතාරය වාදනය කිරීමේදී දකුණු අතේ දබරැඟිල්ලට පළඳින ලෝහ කම්බි මුදුව කුමක්ද?", "මිස්රාබ්", "ජීවා", "ගජය", "කෝණය", "කම්බියකින් නැවී සෑදූ මිස්රාබය දබරැඟිල්ලේ පැළඳ සිතාරයේ තන්තු පිරිමැද වයයි."),
        q("සිතාරයේ දණ්ඩ (ඩාන්ඩ්) මත ස්වර ස්ථාන වෙන් කර දැක්වීමට ගැටගසා ඇති වක්‍රාකාර ලෝහ පටි මොනවාද?", "පර්දා (Frets)", "මණ්කා", "චිකාරි", "ඛූන්ටි", "සිතාරයේ දණ්ඩ මත චලනය කළ හැකි පිත්තල පර්දා බැඳ තිබේ."),
        q("සිතාරයේ ප්‍රධාන වාදන තන්තුවලට යටින් පිහිටා ඇති අනුනාද තන්තු හඳුන්වන්නේ කුමන නමින්ද?", "තරබ් තන්තු", "බාජ් තාර", "ඛරජ් තාර", "චිකාරි තාර", "ප්‍රධාන තන්තු වයන විට ඒවායේ කම්පනයට අනුව ස්වයංක්‍රීයව නාද වන සිහින් තන්තු තරබ් වේ."),
        q("සිතාරයේ පළමු ප්‍රධාන තන්තුව හඳුන්වන නාමය කුමක්ද?", "බාජ් තාරය", "චිකාරි තාරය", "පංචම් තාරය", "තරබ් තාරය", "වැඩිපුරම ස්වර හා ගත් වාදනය කරනු ලබන පළමු තන්තුව බාජ් තාරයයි."),
        q("සිතාරය වාදනයේදී රිද්මය හා තාර ෂඩ්ජය ඇල්ලීම සඳහා පසෙකින් ඇති සිහින් තන්තු දෙක කුමක්ද?", "චිකාරි තන්තු", "ගෝද් තන්තු", "ජෝඩි තන්තු", "මන්ද්‍ර තන්තු", "තාලය පෙන්වීමට හා ජාලා වාදනයේදී චිකාරි තන්තු දෙක භාවිත කෙරේ."),
        q("සිතාරයේ වම් අතේ ඇඟිලිවලින් තන්තුව පසෙකට ඇද ගමක වැනි අලංකාර උපදවන ශිල්ප ක්‍රමය කුමක්ද?", "මීන්ඩ් (Meend)", "දිරි දිරි", "තුප්කා", "ඝසීට්", "පර්දාවක් මත තබා තන්තුව පහළට ඇදීමෙන් අඛණ්ඩ ස්වර ගමනක් හෙවත් මීන්ඩ් නිපදවයි."),
        q("සිතාරයේ දණ්ඩ මත ඇඟිලි ලිස්සා යවමින් පර්දා කිහිපයක් හරහා සිදු කරන වාදන ක්‍රමය කුමක්ද?", "ඝසීට් (Ghaseet)", "බාජ්", "තාලි", "ඛාලි", "තන්තුව මත ඇඟිල්ල ලිස්සා යවමින් පර්දා කිහිපයක ස්වර එකවර ඇසීමට සැලැස්වීම ඝසීට් වේ."),
        q("වයලීනය වාදනය කිරීම සඳහා භාවිත කරනු ලබන අශ්ව කෙඳි යෙදූ ලී උපකරණය කුමක්ද?", "ගජය (Bow)", "මිස්රාබ්", "කඩිප්පුව", "ජවාරිය", "වයලීනය, සාරංගිය සහ එස්රාජ් වැනි තත වාද්‍ය ගජය මගින් පිරිමැද වයනු ලැබේ."),
        q("වයලීනයක් පෙරදිග සංගීතය සඳහා යොදාගැනීමේදී සුසර කරන සම්මත ස්වර පිළිවෙළ කුමක්ද?", "ප - ස - ප - ස", "ග - ම - ධ - නි", "රි - ග - ධ - නි", "ස - රි - ග - ම", "බටහිර G-D-A-E වෙනුවට පෙරදිග සංගීතයේදී ප - ස - ප - ස ලෙස වයලීනය සුසර කෙරේ."),
        q("වයලීනය හා සිතාරය අතර වාදන ක්‍රමය අතින් ඇති ප්‍රධාන වෙනස කුමක්ද?", "වයලීනය ගජයෙන්ද සිතාරය මිස්රාබයෙන්ද වැයීම", "වයලීනය පිඹීමෙන්ද සිතාරය ගැසීමෙන්ද වැයීම", "වයලීනයේ තන්තු 20ක් තිබීම", "සිතාරයේ පර්දා නොමැති වීම", "තත වාද්‍ය වර්ග දෙකක් වුවද වයලීනය ගජයෙන් අඛණ්ඩ නාදයක් ලබාගනී."),
        q("පර්දා නොමැති ලෝහ තහඩුවක් මත ඇඟිලි නියපොතු ගැටීමෙන් වයන භාරතීය තත වාද්‍යය කුමක්ද?", "සරෝද්", "සිතාරය", "එස්රාජ්", "දිල්රුබා", "සරෝද් හි ස්වර පුවරුව සුමට ලෝහ පටියකින් නිමවා ඇති අතර එහි පර්දා නොමැත."),
        q("පොල් කටුව හෝ තුම්බා යොදාගන්නා ගජයෙන් වයන සාම්ප්‍රදායික ඉන්දීය වාද්‍ය භාණ්ඩය කුමක්ද?", "සාරංගිය හෝ එස්රාජ්", "සන්තූරය", "බන්සූරිය", "ජල්තරංග", "සාරංගිය සහ එස්රාජ් යන භාණ්ඩ දෙකම ගජයෙන් වාදනය කරන පෙරදිග වාද්‍ය භාණ්ඩ වේ."),
        q("කුඩා ලී මිටි දෙකකින් තන්තු මත තට්ටු කරමින් වාදනය කරන කාශ්මීර සම්භවයක් ඇති භාණ්ඩය කුමක්ද?", "සන්තූරය", "සරෝද්", "තම්බුරාව", "රබාබ්", "සන්තූරය ත්‍රැපීසියම් හැඩැති ලී පෙට්ටියක් මත තන්තු රැසක් ඇද මිටි දෙකකින් වයන භාණ්ඩයකි."),
        q("තබ්ලාව නිර්මාණය කරන ලද ප්‍රධාන කොටස් දෙක හඳුන්වනු ලබන්නේ කුමන නම්වලින්ද?", "දායා සහ බායා", "සිතාරය සහ තුම්බාව", "ගජය සහ මිස්රාබය", "ඉඩංකු සහ දකුණු බෙරය", "දකුණු අතින් වයන ලී බඳ සහිත කොටස දායා වන අතර වම් අතින් වයන ලෝහ/මැටි කොටස බායා වේ."),
        q("තබ්ලාවේ දායා කොටසේ සම මැද පිහිටි කළු පැහැති වෘත්තාකාර ආලේපනය කුමක්ද?", "සියාහි (ෂායි)", "මෛදාන්", "චාන්ටි", "ගජ්රා", "යකඩ කුඩු හා බත් ආදිය මිශ්‍ර කර සම මැද ආලේප කර ඇති කළු රවුම සියාහි නම් වේ."),
        q("තබ්ලා පෘෂ්ඨයේ සියාහි හා කෙළවර චාන්ටි අතර ඇති සුදු පැහැති මැද සම් ප්‍රදේශය කුමක්ද?", "මෛදාන් (ලව්)", "සියාහි", "බද්දි", "ගට්ටා", "තබ්ලා පෘෂ්ඨයේ සියාහි සහ චාන්ටි අතර මැදි හිස් කලාපය මෛදාන් හෙවත් ලව් ලෙස හැඳින්වේ."),
        q("තබ්ලාවේ දායා හි උඩ කෙළවර වටා පිහිටි ගොතන ලද සම් පටිය හඳුන්වන්නේ කුමන නමින්ද?", "ගජ්රා", "කිනාර්", "සියාහි", "බිණ්ඩි", "තබ්ලාවේ බද්දි පටි සම්බන්ධ කරමින් උඩ දාරය වටා ගොතා ඇති පටිය ගජ්රා නම් වේ."),
        q("තබ්ලාවේ දායා හි බඳ වටා ඇති සම් පටිය අතරට සිර කර තිබෙන කුඩා ලී කැබලි මොනවාද?", "ගට්ටා", "ඛූන්ටි", "මණ්කා", "පර්දා", "තබ්ලාව නියමිත ස්වරයට සුසර කිරීමට ගට්ටා පහළට හෝ ඉහළට මිටියෙන් තට්ටු කරනු ලැබේ."),
        q("තබ්ලාවේ දායා සාමාන්‍යයෙන් සුසර කරනු ලබන්නේ ගායකයාගේ කුමන ස්වරයටද?", "ෂඩ්ජයට (ස) හෝ පංචමයට (ප)", "කෝමල රිෂභයට පමණක්", "තීව්‍ර මධ්‍යමයට පමණක්", "කෝමල ධෛවතයට පමණක්", "ගායකයාගේ ප්‍රධාන ආධාර ස්වරය වන ෂඩ්ජයට තබ්ලාව නිවැරදිව සුසර කෙරේ."),
        q("තබ්ලාවේ බායා හි බඳ සාදා ගැනීමට බහුලව යොදාගන්නා ද්‍රව්‍ය මොනවාද?", "පිත්තල, තඹ හෝ පිළිස්සූ මැටි", "කොස් ලී හා ප්ලාස්ටික්", "උණ බම්බු හා ලබු කබල්", "වීදුරු හා කිරිගරුඬ", "ගැඹුරු බේස් නාදය ලබා ගැනීමට බායා කොටස ලෝහයෙන් හෝ මැටියෙන් තනයි."),
        q("තබ්ලාවේ දායා බඳ තැනීම සඳහා සුදුසුම ශක්තිමත් දැව වර්ගය ලෙස සැලකෙන්නේ කුමක්ද?", "ෂීෂම් (Shisham) හෝ කොස් දැව", "වියළි ලබු කබල", "බට ලීය", "පයින් හා තේක්ක පතුරු", "ෂීෂම් හෝ කොහොඹ, කොස් වැනි ඝන ශක්තිමත් දැවයෙන් දායා බඳ හාරා තනයි."),
        q("තබ්ලාවේ පහළින් බෙරය සමබරව තබා ගැනීමට රෙදි හෝ පිදුරුවලින් සැකසූ වළලු දෙක කුමක්ද?", "ආධාරක වළලු (බිණ්ඩි / චුම්බල)", "ගට්ටා කැබලි", "බද්දි පටි", "මිස්රාබ් වළලු", "තබ්ලාව හෙලවීමකින් තොරව නිශ්චලව තැබීමට රෙදිවලින් එතූ ආධාරක වළලු භාවිත කෙරේ."),
        q("ධ්‍රැපද් හා ධමාර් ගායන සඳහා සාම්ප්‍රදායිකව භාවිත කළ දෙපැත්තෙන්ම සම් ඇති භාරතීය බෙරය කුමක්ද?", "පඛාවජ් (මෘදංගය)", "තබ්ලාව", "ගැටබෙරය", "ඩෝල්කිය", "තබ්ලාව බිහිවීමට පෙර ශාස්ත්‍රීය සංගීතයේ ප්‍රධාන තාල භාණ්ඩය වූයේ පඛාවජයයි."),
        q("ශ්‍රී ලංකාවේ උඩරට නර්තන හා හේවිසි කලාවේ ප්‍රධාන අවනද්ධ වාද්‍ය භාණ්ඩය කුමක්ද?", "ගැටබෙරය", "යක්බෙරය", "තබ්ලාව", "මද්දලය", "දෙකෙළවරට වඩා මැද කොටස මහත්වූ ගැටබෙරය උඩරට සම්ප්‍රදායේ ප්‍රධාන බෙරයයි."),
        q("ගැටබෙරයේ දකුණු ඇස සහ වම් ඇස ආවරණය කිරීමට සාමාන්‍යයෙන් යොදාගන්නා සම් වර්ග මොනවාද?", "වඳුරු සම සහ ගව සම", "මුව සම සහ කිඹුල් සම", "කබර සම සහ එළු සම", "මී ගව සම සහ නරි සම", "උස් හඬ ලබාගන්නා දකුණු පසට වඳුරු සමද, ගැඹුරු හඬ ඇති වම් පසට ගව සමද යොදයි."),
        q("ගැටබෙරයේ බඳ සකස් කිරීම සඳහා සුදුසුම දේශීය දැව වර්ග ලෙස සැලකෙන්නේ මොනවාද?", "කොස්, ඇහැල හෝ කොහොඹ දැව", "පොල් හා කිතුල් කඳන්", "බට ලී හා පුවක් කඳන්", "රබර් හා තේක්ක පතුරු", "ඇහැල, කොහොඹ, ගන්සූරිය සහ කොස් දැව ශක්තිමත් නාදය සඳහා ගැටබෙරයට ගනී."),
        q("ශ්‍රී ලංකාවේ පහතරට තොවිල් හා කෝලම් සඳහා ප්‍රධානව භාවිත කරන දිගැති සිලින්ඩරාකාර බෙරය කුමක්ද?", "යක්බෙරය (දෙවොල් බෙරය)", "ගැටබෙරය", "දවුල", "උඩැක්කිය", "එක සමාන විෂ්කම්භයකින් යුත් සිලින්ඩරාකාර බඳක් ඇති පහතරට බෙරය යක්බෙරයයි."),
        q("යක්බෙරය සාමාන්‍යයෙන් තනනු ලබන දැව වර්ග අතර ප්‍රධාන දැවයක් වන්නේ කුමක්ද?", "ඇහැල, කොස් හෝ කිතුල් දැව", "වියළි උණ බම්බු", "පිත්තල තහඩු", "වියළි ලබු කබල්", "කිතුල්, කොස් හා මිල්ල වැනි දැව යොදා යක්බෙරයේ දිගැති බඳ සකසයි."),
        q("සබරගමු නර්තන සම්ප්‍රදායේ හා විහාරස්ථ හේවිසි වාදනයේ ප්‍රධානව යොදාගන්නා බෙරය කුමක්ද?", "දවුල", "තබ්ලාව", "උඩැක්කිය", "බුම්මැඩිය", "එක් අතකින් හා අනෙක් අතේ ඇති කඩිප්පුවෙන් වයන දවුල හේවිසි වාදනයේ අනිවාර්ය අංගයකි."),
        q("විහාරස්ථ පංචතූර්ය හේවිසි වාද්‍ය කණ්ඩායමට අයත් ප්‍රධාන භාණ්ඩ මොනවාද?", "දවුල, තම්මැට්ටම, හොරණෑව හා තාලම්පට", "සිතාරය, තබ්ලාව, වයලීනය හා බන්සූරිය", "ගිටාරය, පියානෝව, ඩ්‍රම්ස් හා සැක්සෆෝනය", "තම්බුරාව, පඛාවජ්, සරෝද් හා ෂැහනායි", "දවුල, තම්මැට්ටම් යුගලය, හොරණෑව හා තාලම්පට හේවිසි වාදනයේ සාම්ප්‍රදායික අංග වේ."),
        q("බඳ මැටියෙන් හෝ ලීයෙන් සාදා ඇති පෙනුමෙන් කෝප්ප දෙකක් එකට බැඳි ආකාරයේ වාද්‍ය භාණ්ඩය කුමක්ද?", "තම්මැට්ටම", "ගැටබෙරය", "උඩැක්කිය", "මද්දලය", "මුණින් අතට හැරවූ කුඩා බෙර දෙකක් බැඳ කඩිප්පු දෙකකින් වයන්නේ තම්මැට්ටමයි."),
        q("තම්මැට්ටම වාදනය කිරීම සඳහා භාවිත කරනු ලබන වේවැල් හෝ කෝටු කැබලි දෙක හඳුන්වන්නේ කෙසේද?", "කඩිප්පු", "මිස්රාබ්", "ගජය", "බද්දි", "අග කොටස නවා සකසාගත් වේවැල් කඩිප්පු යුගලයෙන් තම්මැට්ටම වයයි."),
        q("තම්මැට්ටමේ වැඩිපුර ගැඹුරු හඬ පිටකරන වම් පැත්තේ කොටස හඳුන්වන්නේ කුමන නමින්ද?", "මන්ද (මන්දම)", "හඬ", "සියාහි", "පර්දා", "තම්මැට්ටමේ ගැඹුරු හඬ දෙන කොටස මන්ද ලෙසත් උස් හඬ දෙන කොටස හඬ ලෙසත් හඳුන්වයි."),
        q("ශිව දෙවියන්ගේ ඩමරුව හා සම්බන්ධ යැයි සැලකෙන මැද සිහින්ව දෙකෙළවර මහත් වූ කුඩා බෙරය කුමක්ද?", "උඩැක්කිය", "දවුල", "තම්මැට්ටම", "යක්බෙරය", "මැද අතින් අල්ලාගෙන ඇඟිලිවලින් තට්ටු කර වයන මැද සිහින් බෙරය උඩැක්කියයි."),
        q("උඩැක්කිය වාදනය කරන අතරතුර බෙරයේ හඬ උස් පහත් කිරීම සඳහා භාවිත කරන කොටස කුමක්ද?", "මැද බැඳ ඇති පටිය (වරපට) මිරිකීම", "ගට්ටා වලට මිටියෙන් ගැසීම", "බෙර ඇසට වතුර ඉසීම", "කඩිප්පුව වෙනස් කිරීම", "බෙරයේ මැද පිහිටි ලණුව අතින් තද කිරීමෙන් හා ලිහිල් කිරීමෙන් ස්වරය වෙනස් කෙරේ."),
        q("මැටියෙන් සාදන ලද බඳක් සහිතව එක් කෙළවරක් පමණක් තලගොයි සමින් වැසූ ජන සංගීත බෙරය කුමක්ද?", "බුම්මැඩිය", "උඩැක්කිය", "ගැටබෙරය", "තබ්ලාව", "කළගෙඩි හැඩැති මැටි බඳක එක් කෙළවරක සමක් බැඳ වයන බුම්මැඩිය ජන නැටුම් සඳහා යොදයි."),
        q("සිංහල අලුත් අවුරුදු සමයේදී කාන්තාවන් වටේට හිඳ ගායනා කරමින් වයන ඒකපාර්ශ්වික බෙරය කුමක්ද?", "බැංකු රබාන (මහ රබාන)", "අත් රබාන", "තම්මැට්ටම", "යක්බෙරය", "රබන් පද ගයමින් කිහිප දෙනෙකු එකවර අත්වලින් වාදනය කරන්නේ බැංකු රබානයි."),
        q("එක් අතකින් අල්ලාගෙන අනෙක් අතින් වයමින් නැටුම් හා විරිදු සඳහා යොදාගන්නා කුඩා රබාන කුමක්ද?", "අත් රබාන", "මහ රබාන", "බුම්මැඩිය", "දවුල", "විරිදු ගායකයන් හා රබන් නැටුම්කරුවන් විවිධ කරණම් දමමින් වයන්නේ අත් රබානය."),
        q("දේශීය හා කර්ණාටක සංගීතයේ එන බෙර අතර නාඩගම් වාදනය සඳහා යොදාගන්නා දෙපැත්තේ සියාහි ඇති බෙරය කුමක්ද?", "මද්දලය", "තම්මැට්ටම", "බුම්මැඩිය", "අත් රබාන", "නාඩගම් කලාවේ ප්‍රධාන තාල භාණ්ඩය වන මද්දලය පඛාවජයට සමාන හැඩයක් ගනී."),
        q("උණ බම්බුවකින් සාදා ඇති උත්තර භාරතීය ශාස්ත්‍රීය සුසිර වාද්‍ය භාණ්ඩය කුමක්ද?", "බන්සූරිය (බටනළාව)", "ෂැහනායි නළාව", "හොරණෑව", "ක්ලැරිනට් නළාව", "වැඩි කපාදු කොටස් රහිත උණ බම්බු නළාව බන්සූරිය නමින් භාරතීය සංගීතයේ භාවිත වේ."),
        q("බන්සූරියක සාමාන්‍යයෙන් ස්වර නිපදවීම සඳහා ඇඟිලි තබන සිදුරු කීයක් පිහිටා තිබේද?", "6 ක් හෝ 7 ක්", "2 ක් පමණක්", "15 ක්", "22 ක්", "පිඹින සිදුරට අමතරව ඇඟිලි තැබීම සඳහා බන්සූරියේ සිදුරු 6ක් හෝ 7ක් ඇත."),
        q("බන්සූරිය පිඹීමේදී ශබ්දය උපදවනු ලබන භෞතික ක්‍රියාවලිය කුමක්ද?", "පිඹින සිදුරේ දාරය මත වායු කඳ කම්පනය වීම", "ද්විත්ව බට පතක් කම්පනය වීම", "තොල් දෙක එකට තද කොට පිඹීම", "තන්තු දෙකක් එකට ගැටීම", "බටනළාවේ දාරයේ වායු ධාරාව ගැටී ඇතුළත වායු කඳ කම්පනය වීමෙන් මිහිරි හඬ උපදී."),
        q("ද්විත්ව පත්‍රිකාවක් භාවිතයෙන් නාද උපදවන භාරතීය සුබ මංගල සුසිර වාද්‍ය භාණ්ඩය කුමක්ද?", "ෂැහනායි", "බන්සූරිය", "සන්තූරය", "සිතාරය", "උත්තර භාරතයේ මංගල කටයුතු හා ශාස්ත්‍රීය ප්‍රසංග සඳහා ෂැහනායි නළාව යොදාගනී."),
        q("දේශීය හේවිසි වාදනයේදී තනුවක් වාදනය කරන එකම සුසිර වාද්‍ය භාණ්ඩය කුමක්ද?", "හොරණෑව", "දවුල", "තම්මැට්ටම", "තාලම්පට", "හේවිසි පූජාවේදී රිද්ම භාණ්ඩ මැද තාල හා තනු රටා වාදනය කරන්නේ හොරණෑවයි."),
        q("දේශීය හොරණෑවේ පහළින්ම ඇති ලෝහ කොටස හඳුන්වනු ලබන්නේ කුමන නමින්ද?", "මුඛරිය / කංසාලය", "ඛූන්ටි කොටස", "තුම්බා කොටස", "ගට්ටා කොටස", "පිත්තලෙන් තැනූ ලොකු වූ පහළ කෙළවර නාදය විහිදුවා හැරීමට උපකාරී වේ."),
        q("හොරණෑවේ පිඹින ස්ථානයේ සවි කරන ද්විත්ව තල් කොළ පත හඳුන්වන්නේ කුමන නමින්ද?", "ඉපියාව (පත)", "ජීවා", "පර්දා", "මිස්රාබ්", "වියළි තල් හෝ තලාපත් කොළයකින් තැනූ ඉපියාව කම්පනය වීමෙන් හොරණෑවේ තීව්‍ර හඬ උපදී."),
        q("ශ්‍රී ලංකාවේ බෞද්ධ ආගමික වතාවත් හා පෙරහැරවලදී මංගල නාදයක් ලෙස පිඹින ස්වාභාවික සුසිර භාණ්ඩය කුමක්ද?", "හක්ගෙඩිය (ශංඛය)", "හොරණෑව", "බන්සූරිය", "තාලම්පට", "මුහුදු බෙල්ලකුගේ කටුවක් සිදුරු කර තනන හක්ගෙඩිය ආගමික හා රාජ්‍ය උත්සවවල පිඹිනු ලැබේ."),
        q("හාමෝනියම් හෙවත් සර්පිනාව තුළ ස්වර හඬ උපදවනු ලබන ප්‍රධාන කොටස කුමක්ද?", "මයිනහමෙන් එන සුළඟට කම්පනය වන ලෝහ පත්‍ර", "ඇතුළත ඇති ලෝහ කම්බි වලට ගසන මිටි", "විදුලි ශබ්ද උත්පාදක පරිපථ", "උණ බට නළා පේළිය", "පිටුපස මයිනහමෙන් පොම්ප කරන වාතය පිත්තල රීඩ්ස් හරහා ගමන් කර හඬ නිපදවයි."),
        q("හාමෝනියම් යතුරු පුවරුවේ එක් සප්තකයක සුදු සහ කළු යතුරු ඇතුළුව මුළු යතුරු ගණන කීයද?", "12 කි", "7 කි", "22 කි", "10 කි", "ශුද්ධ ස්වර 7 සහ විකෘති ස්වර 5 සඳහා සප්තකයක යතුරු 12ක් පිහිටා ඇත."),
        q("හාමෝනියමය පිටුපස ඇති හුළං පොම්ප කරන කොටස හඳුන්වනු ලබන්නේ කුමන නමින්ද?", "මයිනහම (Bellows)", "තුම්බාව", "ගජ්රා", "කඩිප්පුව", "වම් හෝ දකුණු අතින් මයිනහම ඉදිරියට පසුපසට චලනය කර සුළං සපයයි."),
        q("පෙරදිග සංගීතයේදී හාමෝනියමය භාවිතයේ පවතින ප්‍රධාන සීමාවක් ලෙස සැලකෙන්නේ කුමක්ද?", "මීන්ඩ් සහ සියුම් ශ්‍රැති ස්ථාන වැයීමට නොහැකි වීම", "තනිව සප්තක තුනක් නොතිබීම", "හඬ ඉතා අඩු වීම", "සුළං සැපයීමට විදුලිය අවශ්‍ය වීම", "ස්ථිර ස්වර 12කට සීමා වී ඇති නිසා හාමෝනියමයෙන් සියුම් ගමක හා මීන්ඩ් වැයිය නොහැක."),
        q("ජලය පිරවූ පිඟන් මැටි කෝප්ප කිහිපයකට ලී කෝටු දෙකකින් තට්ටු කර වයන ඝන වාද්‍ය භාණ්ඩය කුමක්ද?", "ජල්තරංග", "සන්තූරය", "තාලම්පට", "ඝටම්", "විවිධ ප්‍රමාණයේ කෝප්පවල ජල මට්ටම අඩු වැඩි කර ස්වර සුසර කර ජල්තරංග වයයි."),
        q("ජල්තරංග වාද්‍ය භාණ්ඩයේ කෝප්පයක ඇති ජල ප්‍රමාණය වැඩි කළ විට එම කෝප්පයෙන් නිකුත් වන ස්වරයට කුමක් සිදුවේද?", "ස්වරය පහළ බසී (මන්ද්‍ර වේ)", "ස්වරය ඉහළ නගී (තාර වේ)", "හඬ සම්පූර්ණයෙන් නතර වේ", "වෙනසක් සිදු නොවේ", "කෝප්පයේ ජලය වැඩි වන විට කම්පන සංඛ්‍යාතය අඩු වී ස්වරය පහළ බසී."),
        q("දකුණු ඉන්දීය කර්ණාටක සංගීතයේ බහුලව භාවිත කරන විශේෂිත මැටි කළය හඳුන්වන්නේ කුමන නමින්ද?", "ඝටම් (Ghatam)", "පඛාවජ්", "තම්මැට්ටම", "මද්දලය", "විශේෂ මැටියෙන් පුලුස්සා සකසන ලද ඝටම් නම් කළය ඇඟිලිවලින් තට්ටු කර වයයි."),
        q("පිත්තල හෝ කංසා ලෝහයෙන් සාදා නූලකින් සම්බන්ධ කර ඇති කුඩා තැටි යුගලය කුමක්ද?", "තාලම්පට", "තබ්ලාව", "සන්තූරය", "ජල්තරංග", "තාලයේ ශබ්ද සලකුණු තබාගැනීම සඳහා පිත්තල තාලම්පට යුගලය එකට ගැටීමෙන් වයයි."),
        q("දේශීය හා භාරතීය නර්තනයන්හිදී නැට්ටුවන්ගේ පාදවල බඳින කුඩා ගෙජ්ජි වැල අයත් වන්නේ කුමන වාද්‍ය කාණ්ඩයටද?", "ඝන වාද්‍ය", "සුසිර වාද්‍ය", "තත වාද්‍ය", "ආවනද්ධ වාද්‍ය", "ලෝහ කුහර තුළ කුඩා යකඩ බෝල ගැටී ශබ්ද උපදින නිසා ගෙජ්ජි ඝන වාද්‍ය වේ."),
        q("ලී පතුරු දෙකක් ඇඟිලි අතර තබාගෙන තාලයට ගැසීමෙන් වයන ඝන වාද්‍ය භාණ්ඩය කුමක්ද?", "කර්තාල් (ලී පතුරු)", "බන්සූරිය", "වීණාව", "ඩෝල්කිය", "සකීර් හා කීර්තන් ගායනාවලදී ලී පතුරු සහ කුඩා පිත්තල තැටි සහිත කර්තාල් වයනු ලැබේ."),
        q("උඩරට පන්තේරු නැටුමේදී භාවිත කරන රවුම් රාමුවේ ගෙජ්ජි යෙදූ පිත්තල භාණ්ඩය කුමක්ද?", "පන්තේරුව", "උඩැක්කිය", "තාලම්පට", "තම්මැට්ටම", "වටේට කුඩා ලෝහ පෙති සවි කරන ලද වළල්ලක් බඳු පන්තේරුව දේශීය ඝන වාද්‍ය භාණ්ඩයකි."),
        q("ගෝතම බුදුන් වහන්සේට පූජා පවත්වන තේවා වාදනයන්හිදී 'පංචතූර්ය නාදය' පැවැත්වෙන ප්‍රසිද්ධ විහාරස්ථානය කුමක්ද?", "මහනුවර ශ්‍රී දළදා මාලිගාව", "සීගිරිය ගල් පර්වතය", "ගාලු කොටුව", "යාපනය කොටුව", "දළදා මාලිගාවේ තේවා වතාවත්වලදී දවුල්, තම්මැට්ටම්, හොරණෑ හා හක්ගෙඩි වාදනය පවත්වයි."),
        q("දක්ෂිණ භාරතීය කර්ණාටක සංගීතයේ ප්‍රධාන තත වාද්‍ය භාණ්ඩය ලෙස සැලකෙන වීණා වර්ගය කුමක්ද?", "සරස්වතී වීණාව", "රුද්‍ර වීණාව", "විචිත්‍ර වීණාව", "මෝහන් වීණාව", "ප්‍රධාන තන්තු 4ක් හා තාල තන්තු 3ක් ඇති සරස්වතී වීණාව කර්ණාටක සංගීතයේ මූලික භාණ්ඩයයි."),
        q("උත්තර භාරතයේ ධ්‍රැපද් ගායන සම්ප්‍රදාය හා බැඳුණු පැරණි තත වාද්‍ය භාණ්ඩය කුමක්ද?", "රුද්‍ර වීණාව (බීන්)", "හවායන් ගිටාරය", "මැන්ඩොලිනය", "පියානෝව", "ලබු තුම්බා දෙකක් මත උණ බට දණ්ඩක් සවි කළ රුද්‍ර වීණාව ඉතා පැරණි ගාම්භීර භාණ්ඩයකි."),
        q("නූතන ලෝක සංගීතයේ යතුරු පුවරු වාද්‍ය භාණ්ඩ අතර තන්තු මත කුඩා මිටි වැදීමෙන් නාද උපදවන භාණ්ඩය කුමක්ද?", "පියානෝව", "හාමෝනියමය", "ඇකෝඩියනය", "ඕගනය", "පියානෝවේ යතුරක් එබූ විට ඇතුළත ඇති පීඩන මිටිය ලෝහ කම්බිය මත වැදී නාදය උපදවයි."),
        q("වයලීනය, වියෝලා, චෙලෝ සහ ඩබල් බේස් යන භාණ්ඩ හතර අයත් වන්නේ කුමන බටහිර වාද්‍ය පවුලටද?", "තත වාද්‍ය පවුලට (Strings)", "පිත්තල සුසිර පවුලට (Brass)", "දැව සුසිර පවුලට (Woodwind)", "තාල භාණ්ඩ පවුලට (Percussion)", "බටහිර සිම්ෆනි වාද්‍ය වෘන්දයේ ගජයෙන් වයන ප්‍රධාන තත පවුල මේ හතරයි."),
        q("බටහිර වාද්‍ය වෘන්දයේ 'දැව සුසිර' කාණ්ඩයට අයත් වාද්‍ය භාණ්ඩ යුගලයක් නම් කරන්න.", "ෆ්ලූට් සහ ක්ලැරිනට්", "ට්‍රම්පට් සහ ට්‍රොම්බෝන්", "වයලීන් සහ චෙලෝ", "ටිම්පනි සහ සිම්බල්ස්", "ෆ්ලූට්, ක්ලැරිනට්, ඕබෝ සහ බැසූන් යන භාණ්ඩ දැව සුසිර පවුලට අයත් වේ."),
        q("බටහිර සංගීතයේ 'පිත්තල සුසිර' භාණ්ඩ වාදනය කිරීමේදී ශබ්දය උපදවන්නේ කෙසේද?", "වාදකයාගේ තොල් දෙක කම්පනය කර පිඹීමෙන්", "තන්තු මත ඇඟිලි ගැසීමෙන්", "ලී මිටියකින් තට්ටු කිරීමෙන්", "පත්‍රිකා දෙකක් පිඹීමෙන්", "ට්‍රම්පට්, ෆ්‍රෙන්ච් හෝන් වැනි භාණ්ඩවල මුඛ පටිය තුළ තොල් කම්පනය කිරීමෙන් නාදය උපදවයි."),
        q("නූතන ගිටාරය සාමාන්‍යයෙන් ප්‍රධාන තන්තු කීයකින් සමන්විත වේද?", "6 කින්", "4 කින්", "12 කින්", "8 කින්", "සම්මත ඇකෝස්ටික් හා ඉලෙක්ට්‍රික් ගිටාරයක E-A-D-G-B-E ලෙස තන්තු 6ක් පිහිටයි."),
        q("ගිටාරයේ ගෙල මත ස්වර ස්ථාන වෙන් කර ගැනීමට පිහිටි ලෝහ කොටස් මොනවාද?", "පර්දා (Frets)", "ගජ්රා", "සියාහි", "කඩිප්පු", "ගිටාරයේ ගෙල (Neck) මත ස්ථිර ලෙස සවි කළ ලෝහ පර්දා පිහිටා ඇත."),
        q("බටහිර පියානෝවට වඩා පෙරදිග හාමෝනියමයේ ඇති ප්‍රධාන තාක්ෂණික වෙනස කුමක්ද?", "පියානෝවේ තන්තු ඇති අතර හාමෝනියමයේ රීඩ්ස් ඇත", "පියානෝවේ යතුරු නොමැති වීම", "හාමෝනියමයේ කළු යතුරු නොමැති වීම", "පියානෝව සුළඟින් වැයීම", "පියානෝව තන්තු කම්පනයෙන් නාද වන අතර හාමෝනියමය සුළඟ හා රීඩ්ස් මගින් නාද වේ."),
        q("ජපානයේ සාම්ප්‍රදායික තත වාද්‍ය භාණ්ඩයක් වන 'කොතෝ' භාණ්ඩයේ සාමාන්‍යයෙන් ඇති තන්තු සංඛ්‍යාව කීයද?", "13 කි", "4 කි", "6 කි", "2 කි", "බිම තබා වයන ජපන් සාම්ප්‍රදායික කොතෝ වාද්‍ය භාණ්ඩයේ සේද තන්තු 13ක් පිහිටයි."),
        q("සිංහල සංගීතයේදී දෙපසම තට්ටු කර වයන ගැමි හා කාව්‍ය ගීතවල ජනප්‍රිය දිගැති කුඩා බෙරය කුමක්ද?", "ඩෝල්කිය", "ගැටබෙරය", "තම්මැට්ටම", "බුම්මැඩිය", "දෑතින්ම වයන ඩෝල්කිය නාඩගම්, ජන ගී හා කණ්ඩායම් සංගීතයේ බහුලව භාවිත වේ."),
        q("දේශීය හා කණ්ඩායම් සංගීතයේදී වටේට කුඩා පිත්තල තහඩු කැබලි සවි කළ අත් රබන් විශේෂය කුමක්ද?", "තැම්බොරීන් (Tambourine)", "තම්මැට්ටම", "පඛාවජය", "ගැටබෙරය", "වටේට කුඩා තහඩු කැබලි සහිත අත් රබාන සරල ගී හා කණ්ඩායම් සංගීතයේ භාවිත වේ."),
        q("පහළ ස්වර සඳහා මහත තන්තුද උස් ස්වර සඳහා සිහින් තන්තුද භාවිත කරන වාද්‍ය භාණ්ඩ මොනවාද?", "සිතාරය හා වයලීනය", "තාලම්පට හා ඝටම්", "බන්සූරිය හා හොරණෑව", "තබ්ලාව හා මද්දලය", "සිතාරය හා වයලීනයේ ස්වර සංඛ්‍යාතයට අනුව විවිධ ඝනකමින් යුත් තන්තු යොදාගනී."),
        q("තබ්ලාව පුහුණු වන සිසුවෙකු වයා අවසන් වූ පසු එය ආරක්ෂා කර ගැනීමට කළ යුත්තේ කුමක්ද?", "ආවරණ යොදා වියළි ස්ථානයක තැබීම", "සියාහි මත ජලය ගැල්වීම", "තද අව්වේ තබා වේලීම", "ගට්ටා සියල්ල ගලවා ඉවත් කිරීම", "තෙතමනය හා දැඩි උෂ්ණත්වය සම හා සියාහි විනාශ කරන නිසා ආවරණ යොදා තබාගත යුතුය."),
        q("පිත්තලෙන් තැනුවද තනි උණ පත්‍රිකාවක් මගින් නාද උපදවන බැවින් දැව සුසිර ගණයට අයත් භාණ්ඩය කුමක්ද?", "සැක්සෆෝනය", "ට්‍රම්පට් නළාව", "බන්සූරිය", "තාලම්පට", "පිත්තල බඳක් තිබුණද රීඩ් එකක් භාවිත වන නිසා සැක්සෆෝනය දැව සුසිර පවුලට අයත් වේ."),
        q("එකට සවි කළ කුඩා අවනද්ධ බෙර දෙකක් දෑතින් වයන ලතින් ඇමරිකානු රිද්ම භාණ්ඩය කුමක්ද?", "බොංගෝ (Bongo)", "පඛාවජ්", "ගැටබෙරය", "තම්මැට්ටම", "ලොකු හා කුඩා බෙර දෙකක් එකට සම්බන්ධ කළ බොංගෝ ලතින් හා සරල ගී රිද්ම සඳහා ගනී."),
        q("කොංගා බෙර යුගලය සිංහල සරල ගී වාද්‍ය වෘන්දයේදී ප්‍රධානව යොදාගන්නේ කුමක් සඳහාද?", "තාල හා රිද්ම ආධාරකය ලෙස", "රාග ආලාප වැයීමට", "ශ්‍රැති ආධාරකය ලෙස", "මීන්ඩ් අලංකාර වැයීමට", "උසට තබා ඇඟිලි හා අත්ලෙන් වයන කොංගා බෙර සරල ගීතයේ රිද්ම රටා අලංකාර කරයි."),
        q("ශ්‍රී ලාංකේය පහතරට තොවිල් හා කෝලම් සංගීතයේදී ප්‍රධාන වශයෙන් යොදාගන්නා වාද්‍ය භාණ්ඩ යුගලය කුමක්ද?", "යක්බෙරය හා හොරණෑව", "සිතාරය හා සරෝද්", "රුද්‍ර වීණාව හා තම්බුරාව", "කොතෝ වීණාව හා බන්සූරිය", "පහතරට ශාන්තිකර්ම, කෝලම් හා පෙරහැරවලදී යක්බෙරය හා හොරණෑව ප්‍රධාන වේ."),
        q("ඉන්දියාවේ සුප්‍රකට තබ්ලා වාදකයෙකු වන උස්තාද් සාකීර් හුසේන් කුමන ඝරානාවට අයත්ද?", "පංජාබ් ඝරානාව", "දිල්ලි ඝරානාව", "ලක්නව් ඝරානාව", "බෙනාරස් ඝරානාව", "තබ්ලා වාදනයේ මහැදුරු අල්ලා රක්ඛාගේ පුත් සාකීර් හුසේන් පංජාබ් ඝරානාව නියෝජනය කරයි."),
        q("ඉන්දියානු 'ශ්‍රැති පෙට්ටිය' සහ තම්බුරාව අතර ඇති පොදු කාර්යය කුමක්ද?", "නිවැරදි මූලික ස්වරය නොකඩවා සැපයීම", "වේගවත් තාල පද වැයීම", "බෙර හඬ අනුකරණය කිරීම", "විශාල හඬක් නිකුත් කිරීම පමණක්", "තම්බුරාව මෙන්ම ශ්‍රැති පෙට්ටියද ගායනයේදී ස්ථිර ෂඩ්ජ පංචම ශ්‍රැති පදනම ලබාදේ."),
        q("පෙරදිග සංගීතයේදී වයලීනය වාදනය කරන සම්ප්‍රදායික ඉරියව්ව කුමක්ද?", "බිම හිඳ වම් පාදය මත සිර කරගෙන", "උරහිස මත තබා සිටගෙන පමණක්", "හිස මත තබාගෙන", "මේසයක් මත හරහට තබා", "බටහිර මෙන් උරහිසේ නොතබා, හිඳගෙන වම් පාදයේ වළලුකරට හේත්තු කර පෙරදිග වයලීනය වයයි."),
        q("දැව හෝ ලබු තුම්බා දෙක මත දණ්ඩ තබා කුඩා වීදුරු බෝලයකින් තන්තු මත ලිස්සා වයන භාණ්ඩය කුමක්ද?", "විචිත්‍ර වීණාව", "සිතාරය", "තම්බුරාව", "සන්තූරය", "පර්දා නොමැති තන්තු මත වීදුරු කැබැල්ලක් ලිස්සා යවා මේ භාණ්ඩය වයයි."),
        q("ජාත්‍යන්තර හෝන්බොස්ටල්-සැක්ස් වර්ගීකරණයේදී සුසිර වාද්‍ය භාණ්ඩ හඳුන්වනු ලබන්නේ කුමන නමින්ද?", "ඒරෝෆෝන් (Aerophones)", "කෝඩෝෆෝන් (Chordophones)", "මෙම්බ්‍රනෝෆෝන් (Membranophones)", "ඉඩියෝෆෝන් (Idiophones)", "වාතය කම්පනයෙන් නාද උපදවන භාණ්ඩ Aerophones ලෙස ජාත්‍යන්තරව වර්ග කෙරේ."),
        q("ජාත්‍යන්තර වාද්‍ය භාණ්ඩ වර්ගීකරණයේදී තන්තු භාණ්ඩ හඳුන්වනු ලබන පොදු නාමය කුමක්ද?", "කෝඩෝෆෝන් (Chordophones)", "ඉඩියෝෆෝන් (Idiophones)", "ඒරෝෆෝන් (Aerophones)", "මෙම්බ්‍රනෝෆෝන් (Membranophones)", "සිතාරය, වයලීනය, ගිටාරය, තම්බුරාව වැනි තන්තු භාණ්ඩ Chordophones ගණයට වැටේ.")
    )
}
